    try:
        ftp.cwd(ftp_dir)
    except Exception as e:
        raise Exception(f"Failed to change to directory {ftp_dir} on server {ftp_server}: {str(e)}")
    files = ftp.nlst()
    downloaded_files = []
    for file in files:
        subprocess.run(['wget', f'ftp://{ftp_server}{ftp_dir}/{file}', '--ftp-user=' + ftp_user, '--ftp-password=' + ftp_password], shell=True)
